export const dictionaries: Record<Locale, Messages> = { it, en, fr, es, de };

export function isLocale(value: unknown): value is Locale {
  return typeof value === "string" && locales.includes(value as Locale);
}

export function getMessages(locale: Locale): Messages {
  return dictionaries[locale];
}

export function translate(locale: Locale, key: string, values?: Record<string, string | number>): string {
  const template = dictionaries[locale][key] ?? dictionaries.it[key] ?? key;
  if (!values) return template;
  return Object.entries(values).reduce((copy, [name, value]) => copy.replaceAll(`{${name}}`, String(value)), template);
}

export function translateCatalogFallback(locale: Locale, value: string | null | undefined): string | null {
  if (!value || locale === "it") return value ?? null;
  const dictionary: Record<string, Record<Exclude<Locale, "it">, string>> = {
    Donna: { en: "Women", fr: "Femme", es: "Mujer", de: "Damen" },
    Uomo: { en: "Men", fr: "Homme", es: "Hombre", de: "Herren" },
    Accessori: { en: "Accessories", fr: "Accessoires", es: "Accesorios", de: "Accessoires" },
    Scarpe: { en: "Shoes", fr: "Chaussures", es: "Calzado", de: "Schuhe" },
    Borse: { en: "Bags", fr: "Sacs", es: "Bolsos", de: "Taschen" },
    Bianco: { en: "White", fr: "Blanc", es: "Blanco", de: "Weiß" },
    Nero: { en: "Black", fr: "Noir", es: "Negro", de: "Schwarz" },
    Rosso: { en: "Red", fr: "Rouge", es: "Rojo", de: "Rot" },
    Blu: { en: "Blue", fr: "Bleu", es: "Azul", de: "Blau" },
    Beige: { en: "Beige", fr: "Beige", es: "Beige", de: "Beige" },
    Marrone: { en: "Brown", fr: "Marron", es: "Marrón", de: "Braun" },
    Verde: { en: "Green", fr: "Vert", es: "Verde", de: "Grün" },
  };
  return dictionary[value]?.[locale] ?? value;
}
